    "caseText": "食品製造会社の創業者である高橋さんは2024年に退任する。役員在任期間は30年7か月、退職金は4,100万円。ほかの退職手当、重複期間、障害による退職はない。会社は製品事故・施設事故・従業員事故への備えも検討する。今回比較する契約の対象は、PL賠償＝引渡し後の製品に起因する第三者損害、施設賠償＝施設管理の欠陥に起因する第三者損害、使用者賠償＝従業員の業務上災害について会社が負う法律上の損害賠償責任、と仮定する。各免責や限度額は別途確認する。",
    "question": "退職所得控除額はいくらか。",
